-- Demo handwritten signatures (migration 028): a COA is issued only by someone with a scan of their handwritten
-- signature and a title on file. Fictional demo images for the demo signers. Alex's own account (akiddle) is left
-- without one: a lab administrator records his in Admin > People and groups ("COA signature").
BEGIN;
SET search_path = lims, public;
SELECT set_config('lims.user_id', (SELECT id::text FROM app_user WHERE username = 'akiddle'), true);
SELECT set_config('lims.reason', 'Sandbox demo data', true);
DO $$ DECLARE d uuid; u RECORD; BEGIN
  PERFORM set_config('lims.group_sync', '1', true);
  SELECT id, signature_document_id INTO u FROM app_user WHERE username = 'projmgr';
  IF u.id IS NOT NULL AND u.signature_document_id IS NULL THEN
    INSERT INTO document_file (file_name, mime_type, size_bytes, sha256, content)
    VALUES ('signature-projmgr.png', 'image/png', 6582, encode(sha256(decode('', 'base64')), 'hex'), decode('', 'base64')) RETURNING id INTO d;
    UPDATE app_user SET signature_document_id = d, title = COALESCE(title, 'Project Manager'), signature_set_at = clock_timestamp(), signature_set_by = current_app_user() WHERE id = u.id;
  END IF;
  SELECT id, signature_document_id INTO u FROM app_user WHERE username = 'qa.reviewer';
  IF u.id IS NOT NULL AND u.signature_document_id IS NULL THEN
    INSERT INTO document_file (file_name, mime_type, size_bytes, sha256, content)
    VALUES ('signature-qa.reviewer.png', 'image/png', 6772, encode(sha256(decode('', 'base64')), 'hex'), decode('', 'base64')) RETURNING id INTO d;
    UPDATE app_user SET signature_document_id = d, title = COALESCE(title, 'QA Manager'), signature_set_at = clock_timestamp(), signature_set_by = current_app_user() WHERE id = u.id;
  END IF;
  SELECT id, signature_document_id INTO u FROM app_user WHERE username = 'labsup';
  IF u.id IS NOT NULL AND u.signature_document_id IS NULL THEN
    INSERT INTO document_file (file_name, mime_type, size_bytes, sha256, content)
    VALUES ('signature-labsup.png', 'image/png', 7070, encode(sha256(decode('', 'base64')), 'hex'), decode('', 'base64')) RETURNING id INTO d;
    UPDATE app_user SET signature_document_id = d, title = COALESCE(title, 'Laboratory Supervisor'), signature_set_at = clock_timestamp(), signature_set_by = current_app_user() WHERE id = u.id;
  END IF;
  PERFORM set_config('lims.group_sync', '', true);
END $$;
COMMIT;
